await safe('warmupTarget',async()=>{
  const ex=Object.values(getPlan()).flatMap(d=>d.ex).find(e=>isCompoundEx(e)&&getLastW(e.id));
  if(!ex){if(getWarmupSets(getPlan().A.ex.find(e=>isCompoundEx(e))||null)!==null)throw new Error('calentamiento sin historial');return;}
  S.logs[ex.id]={};
  // 05: el objetivo del calentamiento es el de hoy del Coach de carga (también si toca bajar); redondeo al salto del equipo
  const lw=+getLastW(ex.id).v,s=sugW(ex.id),exp=s?+s.v:lw,st=loadStepOf(ex);
  if(getWarmupTarget(ex)!==exp)throw new Error('objetivo '+getWarmupTarget(ex)+'≠'+exp);
  const wu=getWarmupSets(ex);
  if(exp>=20&&(!wu||wu[1].w!==+(Math.round(exp*0.75/st)*st).toFixed(2)))throw new Error('series de calentamiento');
});
