    _apply5({id:'change_rep_scheme_c4',type:'rep_scheme',basis:'stagnant',exId:'c4',dayKey:'C',to:{s:3,r:12},title:'Cambiar esquema',diff:'3×8 → 3×12',short:'pasar a 3×12 con algo menos de peso'});
    p=P('c4');if(p.kind!=='down'||!(p.weight<30&&p.weight>=27-1e-9)||p.reps!==10||!/nuevo esquema 3×12, con algo menos de peso/.test(p.reason))throw new Error('3×12 → '+T(p)+' '+p.reason);
