await safe('mmEngineApi',async()=>{
  if(typeof GymAnim.muscleMap!=='function'||typeof GymAnim.unmount!=='function')throw new Error('falta muscleMap/unmount');
  // (bloque 4) todo el catálogo tiene su animación (las 46 de siempre incluidas) y ninguna clave queda fuera de él
  _animAll('ejercicios');
  const el=document.createElement('div');el.style.cssText='width:300px;height:200px';document.body.appendChild(el);
  try{
    const h=GymAnim.muscleMap(el,{weights:{quads:.8,hams:2,nope:1,lats_R:.5,abs:-1}});
    const w=h.weights;
    if(w.quads!==.8||w.hams!==1||'nope' in w||w.lats_R!==.5||'abs' in w)throw new Error('pesos saneados '+JSON.stringify(w));
    const cv=el.querySelector('canvas');
    if(!cv||cv.getAttribute('role')!=='img')throw new Error('sin canvas');
    // Actualizar sin volver a montar: mismo canvas y mismo handle
    const h2=GymAnim.muscleMap(el,{weights:{biceps:.5}});
    if(h2!==h||el.querySelectorAll('canvas').length!==1||el.querySelector('canvas')!==cv||JSON.stringify(h.weights)!=='{"biceps":0.5}')throw new Error('no actualiza en su sitio');
    h.setWeights({pecs:1});if(h.weights.pecs!==1)throw new Error('setWeights');
    h.draw();const f=h.frames;h.draw();if(h.frames!==f+1)throw new Error('draw síncrono');
    h.setView('front');if(h.view!=='front')throw new Error('setView');h.setView('both');
    if(!GymAnim.unmount(el)||el.querySelector('canvas')||el._gm)throw new Error('unmount del mapa');
    // unmount de una animación de ejercicio, y el mapa sustituye a una animación montada
    GymAnim.mount(el,'lib_squat_smith');if(!el._ga)throw new Error('mount');
    GymAnim.unmount(el);if(el._ga||el.querySelector('canvas'))throw new Error('unmount de la animación');
    GymAnim.mount(el,'lib_squat_smith');GymAnim.muscleMap(el,{weights:{quads:1}});
    if(el._ga||!el._gm||el.querySelectorAll('canvas').length!==1)throw new Error('mapa sobre animación');
    GymAnim.unmount(el);
  }finally{el.remove();}
});
