    // al verse, se genera; y el siguiente pintado ya la trae puesta (sin parpadeo)
    far.style.top='0';far.style.position='fixed';document.getElementById('screen').dispatchEvent(new Event('scroll'));for(let i=0;i<150&&f.getAttribute('data-ga-st')!=='ok';i++)await W(20);
    if(f.getAttribute('data-ga-st')!=='ok')throw new Error('al verse no se genera');
