  const bad=[];const E=(c,m)=>{if(!c)bad.push(m);};const t0=S.tab,o0=S.open;
  const EMO=/[🏆🎯🧘🌴⏱🔥✅💡📈📊⏳🔄⚠📅⏰🧠🔧🎉🚀😌🥵]/u;
